INSERT OR REPLACE INTO LocalizedText (Language, Tag, Text)
VALUES
	("en_US",			"LOC_TRAIT_LEADER_GEDEMO_MUTOTA_LTRAIT_DESCRIPTION",								"'Early Empire' and 'Feudalism' Civic each provides an [ICON_TradeRoute] Trade Route Capacity. Units that start their turn adjacent to river gain +5 [ICON_Strength] Combat Strength.[ICON_TradeRoute] Trade Routes get +1 [ICON_Culture] Culture for each Camp and Plantation at the destination."),
	("zh_Hans_CN",		"LOC_TRAIT_LEADER_GEDEMO_MUTOTA_LTRAIT_DESCRIPTION",								"“帝国初期”和“封建主义”市政各解锁一个 [ICON_TradeRoute] 贸易路线容量。相邻河流开始回合的单位+5 [ICON_STRENGTH] 战斗力。[ICON_TradeRoute] 贸易路线从目的地每个种植园和营地获得+1 [ICON_CULTURE] 文化值。"),
    ("en_US",			"LOC_TRAIT_CIVILIZATION_GEDEMO_ZIMBABWE_CIV_TRAIT_DESCRIPTION",						"+1 [ICON_CULTURE] Culture, +1 [ICON_FOOD] Food to Farm, Plantation, Pasture and Camp that built on Savannah, +1 [ICON_CULTURE] Culture, +1 [ICON_PRODUCTION] Production to Quarry, Lumber Mill and Mine that built on Savannah."),
	("zh_Hans_CN",		"LOC_TRAIT_CIVILIZATION_GEDEMO_ZIMBABWE_CIV_TRAIT_DESCRIPTION",						"建造在稀树草原上的农场、种植园、牧场、营地+1 [ICON_CULTURE] 文化+1 [ICON_FOOD] 粮食，采石场、矿山、伐木场+1 [ICON_CULTURE] 文化+1 [ICON_PRODUCTION] 生产力。"),
    ("en_US",			"LOC_IMPROVEMENT_GEDEMO_DZIMBABWE_DESCRIPTION",						                "Unlocks the Builder ability to construct Dzimbabwes, unique to Great Zimbabwe.[NEWLINE][NEWLINE]+1 [ICON_FOOD] Food. +1 [ICON_PRODUCTION] Production.+1 [ICON_PRODUCTION] Production from every adjacent Plantation, Camp, Mine, Pasture and Quarry, upgrade to +2 [ICON_PRODUCTION] Production after researching 'Mercantilism' Civic.+1 [ICON_CULTURE] Culture from every adjacent Plantation, Camp, Mine, Pasture and Quarry after researching 'Record History' Civic. Can built on Savannah or Volcano Soil, but can not built adjacent to another Dzimbabwe.Can built on Flood Plains after researching 'Buttress' Technology."),
	("zh_Hans_CN",		"LOC_IMPROVEMENT_GEDEMO_DZIMBABWE_DESCRIPTION",						                "解锁建造者建造津巴布韦特色改良设施津巴布韦石城的能力。[NEWLINE][NEWLINE]+1 [ICON_FOOD] 食物、+1 [ICON_PRODUCTION] 生产力。每相邻一个牧场、营地、矿山、采石场、种植园+1 [ICON_PRODUCTION] 生产力，研究“重商主义”市政后改为+2 [ICON_PRODUCTION] 生产力；研究“历史记录”市政后，每相邻一个牧场、营地、矿山、采石场、种植园+1 [ICON_CULTURE] 文化。可以建造在稀树草原和火山土上，但不能相邻另一个津巴布韦石城建造，研究“扶壁”科技后，可以建造在泛滥平原上。");